//! Independent reference: native PixPin path/draw functions replayed against
//! Qt 5, not generated by Clivuu's geometry. The atlas lives in tests/fixtures.
use clivuu_core::{
    annotation::{
        Kind, Mark,
        arrow::{ArrowType, LineStyle},
    },
    image,
};
use clivuu_desktop::editor::render::{AnnotationNodes, MosaicTextures};
use gtk::{gdk, graphene, prelude::*};
use serde_json::json;
use std::sync::Arc;
pub fn check(window: &gtk::Window) -> Vec<serde_json::Value> {
    let reference = clivuu_core::image_ops::decode(include_bytes!(
        "../../../tests/fixtures/pixpin-arrow-reference.png"
    ))
    .unwrap();
    // User-added headless lines have a separate Qt drawLines reference; they
    // are deliberately not described as a recovered PixPin arrow type.
    let plain_reference = clivuu_core::image_ops::decode(include_bytes!(
        "../../../tests/fixtures/plain-line-reference.png"
    ))
    .unwrap();
    let mut atlas = image::RgbaImage::from_pixel(2860, 400, image::Rgba([255, 255, 255, 255]));
    let mut results = vec![];
    for (row, line) in LineStyle::ALL.into_iter().enumerate() {
        for (col, kind) in ArrowType::ALL.into_iter().enumerate() {
            let (source, source_col) = if kind == ArrowType::PlainLine {
                (&plain_reference, 0)
            } else {
                (&reference, col)
            };
            let mut mark = Mark::new(Kind::Arrow, [30., 40.], 1.);
            mark.points = Arc::new(vec![[30., 40.], [230., 40.]]);
            mark.style.width = 5.;
            mark.style.color = "#ff0000".into();
            mark.style.arrow_type = kind;
            mark.style.line_style = line;
            let node = AnnotationNodes::default()
                .compose(&[mark], &window.pango_context(), &MosaicTextures::new())
                .unwrap();
            let s = gtk::Snapshot::new();
            let bounds = graphene::Rect::new(0., 0., 260., 80.);
            s.append_color(&gdk::RGBA::WHITE, &bounds);
            s.append_node(node);
            let texture = window
                .renderer()
                .unwrap()
                .render_texture(s.to_node().unwrap(), Some(&bounds));
            let mut rgba = vec![0; 260 * 80 * 4];
            texture.download(&mut rgba, 260 * 4);
            let ink = |x: usize, y: usize| rgba[(y * 260 + x) * 4 + 1] < 128;
            let ref_ink = |x: usize, y: usize| {
                source.get_pixel((source_col * 260 + x) as u32, (row * 80 + y) as u32)[1] < 128
            };
            let mut wrong = 0;
            let mut actual = 0;
            let mut expected = 0;
            for y in 1..79 {
                for x in 1..259 {
                    let a = ink(x, y);
                    let b = ref_ink(x, y);
                    actual += usize::from(255 - rgba[(y * 260 + x) * 4 + 1]);
                    expected += usize::from(
                        255 - source
                            .get_pixel((source_col * 260 + x) as u32, (row * 80 + y) as u32)[1],
                    );
                    // Different rasterizers may put an antialiased edge on either
                    // side of a pixel. Interior ink and gaps must still agree.
                    if a && !(y - 1..=y + 1).any(|yy| (x - 1..=x + 1).any(|xx| ref_ink(xx, yy)))
                        || b && !(y - 1..=y + 1).any(|yy| (x - 1..=x + 1).any(|xx| ink(xx, yy)))
                    {
                        wrong += 1;
                    }
                    atlas.put_pixel(
                        (col * 260 + x) as u32,
                        (row * 80 + y) as u32,
                        image::Rgba([
                            255,
                            rgba[(y * 260 + x) * 4 + 1],
                            rgba[(y * 260 + x) * 4],
                            255,
                        ]),
                    );
                }
            }
            results.push(json!({"name":format!("{} reference pixels: {} / {}",if kind==ArrowType::PlainLine {"Qt plain-line"} else {"PixPin"},kind.label(),line.label()),
                "passed":wrong<=4 && actual.abs_diff(expected)<=expected/30+4*255,"unmatched_interior":wrong,"actual_ink":actual,"reference_ink":expected}));
        }
    }
    if let Ok(path) = std::env::var("CLIVUU_TEST_DIR") {
        atlas
            .save(std::path::Path::new(&path).join("clivuu-arrow-atlas.png"))
            .unwrap();
    }
    results
}
